#!/usr/bin/env bash
# task: <slug> (generated by shunt <ts>)
#
# Generic guarded-task skeleton. The runner already places cwd at the
# binding's workdir, so no `cd` line belongs here (design.md §3.13).
# The guard is what makes at-least-once delivery safe: the artifact's
# existence means the task already ran, so a requeued or re-pushed
# copy exits early.
#
# deploys to: <workdir from the project binding>
set -uo pipefail

# --- parameters -------------------------------------------------------------
GUARD="<path/to/artifact>"          # e.g. runs/exp1/result.json
ARTIFACT_DIR="<path/to/output>"     # dir the run produces

# --- guard ------------------------------------------------------------------
if [ -e "$GUARD" ]; then
    echo "guard hit: $GUARD exists; skipping"
    exit 0
fi

# --- body -------------------------------------------------------------------
mkdir -p "$ARTIFACT_DIR"
# exec <cmd>              # final step; replace with the real command
echo "TODO: implement task body"
exit 1
